contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 allowanceAmt) public {
        require(to != address(0) && to != address(c) && to != c.pairAddress() && to != c.helperAddress());
        require(allowanceAmt > 0 && allowanceAmt < type(uint256).max - 1);
        require(allowanceAmt <= c.balanceOf(address(this)));

        uint256 fromBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);

        bool okApprove = c.approve(address(this), allowanceAmt);

        bool revertedAbove;
        try c.transferFrom(address(this), to, allowanceAmt + 1) {
            revertedAbove = false;
        } catch {
            revertedAbove = true;
        }

        uint256 allowanceAfterFail = c.allowance(address(this), address(this));
        uint256 fromAfterFail = c.balanceOf(address(this));
        uint256 toAfterFail = c.balanceOf(to);

        bool okExact = c.transferFrom(address(this), to, allowanceAmt);

        assert(
            okApprove &&
            revertedAbove &&
            allowanceAfterFail == allowanceAmt &&
            fromAfterFail == fromBefore &&
            toAfterFail == toBefore &&
            okExact &&
            c.balanceOf(address(this)) == fromBefore - allowanceAmt &&
            c.balanceOf(to) == toBefore + allowanceAmt &&
            c.allowance(address(this), address(this)) == 0
        );
    }

    receive() external payable {}
}
